{
  "type": "object",
  "description": "Representação dos campos de resposta de uma solicitação de alteração de boleto bancário.",
  "required": [
    "retorno",
    "titulo"
  ],
  "properties": {
    "retorno": {
      "type": "string",
      "maxLength": 2,
      "minLength": 2,
      "pattern": "^\\d{2}$",
      "description": "Código de retorno para identificar o resultado do processo de solicitação de alteração do boleto.\n - 01 = Solicitado com sucesso: significa que a solicitação retornou com sucesso, mas a alteração ainda não está disponível na base centralizada de títulos para pagamento interbancário.\n- 02 = Sucesso: significa que a alteração do título retornou com sucesso. \n - 04 = Homologado: significa que os testes foram efetuados com sucesso.",
      "example": "04"
    },
    "titulo": {
      "type": "object",
      "description": "Representação dos campos de boletos bancários.",
      "required": [
        "nosso_numero",
        "codigo_barras",
        "linha_digitavel",
        "beneficiario",
        "instrucoes"
      ],
      "properties": {
        "nosso_numero": {
          "type": "string",
          "minLength": 10,
          "maxLength": 10,
          "pattern": "^\\d{10}$",
          "description": "Número de identificação do título no banco.",
          "example": "0000000264"
        },
        "codigo_barras": {
          "type": "string",
          "pattern": "^\\d{44}$",
          "maxLength": 44,
          "minLength": 44,
          "description": "Código de barras do título.",
          "example": "04191808600000500002100100000010588549074094"
        },
        "linha_digitavel": {
          "type": "string",
          "pattern": "^\\d{47}$",
          "maxLength": 47,
          "minLength": 47,
          "description": "Linha digitável do título.",
          "example": "04192100180000001058785490740942180860000050000"
        },
        "beneficiario": {
          "type": "object",
          "description": "Informações pertinentes ao beneficiário.",
          "required": [
            "codigo"
          ],
          "properties": {
            "codigo": {
              "type": "string",
              "maxLength": 13,
              "pattern": "^\\d{13}$",
              "description": "Número do convênio. Código completo do Beneficiário, composto por: Número da agência (4 dígitos), código do beneficiário (7 dígitos) e número de controle (2 dígitos). Preenchido com zeros à esquerda cada complemento.",
              "example": "0010000001088"
            }
          }
        },
        "instrucoes": {
          "type": "object",
          "description": "Instruções de pagamento do boleto para alteração: abatimento",
          "required": [
            "abatimento"
          ],
          "properties": {
            "abatimento": {
              "type": "object",
              "description": "Informações da instrução de abatimento.",
              "required": [
                "valor"
              ],
              "properties": {
                "valor": {
                  "type": "string",
                  "pattern": "^-?\\d{1,12}\\.\\d{2}$",
                  "maxLength": 15,
                  "description": "Valor do abatimento.",
                  "example": "6.80"
                }
              }
            }
          }
        }
      }
    }
  }
}

