{
  "type": "object",
  "description": "Representação de um objeto com os erros identificados. Contém uma lista de erros.",
  "required": [
    "ocorrencias"
  ],
  "properties": {
    "ocorrencias": {
      "type": "array",
      "minItems": 1,
      "maxItems": 5,
      "items": {
        "type": "object",
        "description": "Ocorrência de erro.",
        "required": [
          "codigo",
          "mensagem"
        ],
        "properties": {
          "codigo": {
            "type": "string",
            "maxLength": 20,
            "pattern": "^[A-Za-z0-9]{1,20}$",
            "description": "Código do erro.",
            "example": "54"
          },
          "mensagem": {
            "type": "string",
            "maxLength": 300,
            "pattern": "^[A-Za-z0-9áàâãéêíóôõúüçÁÀÂÃÉÊÍÓÔÕÚÜÇ \\\\!#$%'()*+,-./:;=?@[\\]^_`{|}~&]{1,300}$",
            "description": "Descrição do erro.",
            "example": "Erro XXX."
          },
          "complemento": {
            "type": "string",
            "maxLength": 20,
            "pattern": "^[A-Za-z0-9 -]{1,20}$",
            "description": "Complemento para identificação de um erro específico.",
            "example": "OC4B0004"
          }
        }
      }
    }
  }
}
